head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > E > ondateselect]<br/>팝업 달력에서 날짜 영역의 선택일을 변경했을때 발생합니다.",
    "validation" : [
        "팝업 달력에서 날짜 영역의 선택일을 변경했을때 발생합니다.",        
        "date 파라미터로 변경된 선택일을 ioFormat 속성에 설정된 포맷에 맞게 갖습니다.",
        "ioFormat 속성을 설정하지 않으면 date 파라미터로 calendarValueType 속성값에 맞게 'yyyyMMddHHmmSS' 포맷이 잘려서 적용됩니다.",
        "dateObject 파라미터로 변경된 선택일을 Date 객체로 갖습니다.",
        "Date 객체는 1970년 1월 1일(UTC) 자정으로부터 경과한 시간을 밀리초(ms) 단위의 정수로 저장합니다.",
        "키보드를 사용하여 팝업 달력의 선택일을 변경한 경우도 ondateselect 이벤트가 발생합니다.",
        "키보드를 사용하여 팝업 달력의 선택일을 변경한 경우도 ondateselect 이벤트가 발생합니다.",
        "팝업 달력에서 '이전달', '이후달', '이전연월', '다음연월' 버튼 클릭으로 ondateselect 이벤트가 발생하지 않습니다.",
        "팝업 달력에서 '확인' 버튼을 클릭하여 선택일이 컴포넌트에 반영될때는 ondateselect 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : "yearMonthDateTimeSec",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["ondateselect"]);

    // comp 생성 함수 호출
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();    

    strTarget += '<w2:inputCalendar ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:200px; height:23px;"></w2:inputCalendar>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "inputCalendar",
        strTarget,
        grp_comp
    );    

    target1.setValue("20251111031509");
}



scwin.target1_ondateselect = function (date, dateObject) {    
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ondateselect 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("date : " + date);    
    wf_body_bottom.getObj("scwin").setReturnValue("dateObject : " + dateObject);    
    wf_body_bottom.getObj("scwin").setReturnValue("dateObject.getTime() : " + dateObject.getTime());    
}
